def run_length_encode(text):
    if not text:
        return ""

    encoded = []
    count = 1

    for i in range(1, len(text)):
        if text[i] == text[i - 1]:
            count += 1
        else:
            encoded.append(str(count) + text[i - 1])
            count = 1

    # Append the last run
    encoded.append(str(count) + text[-1])

    return ''.join(encoded)

# Demo
if __name__ == "__main__":
    example_text = "aaabcc"
    result = run_length_encode(example_text)
    print(result)  # Output: '3a1b2c'

def balanced_brackets(text):
    stack = []
    brackets = {')': '(', '}': '{', ']': '['}

    for char in text:
        if char in brackets.values():
            stack.append(char)
        elif char in brackets.keys():
            if not stack or stack.pop() != brackets[char]:
                return False

    return len(stack) == 0

# Demo
if __name__ == "__main__":
    example_text = "{[()]}{}"
    result = balanced_brackets(example_text)
    print(result)  # Output: True

def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start time
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]

    for interval in intervals[1:]:
        last_merged = merged[-1]
        if interval[0] <= last_merged[1]:
            # Merge overlapping or touching intervals
            merged[-1] = (last_merged[0], max(last_merged[1], interval[1]))
        else:
            # Add non-overlapping interval
            merged.append(interval)

    return merged

# Demo
if __name__ == "__main__":
    example_intervals = [[1, 3], [2, 6], [8, 10]]
    result = merge_intervals(example_intervals)
    print(result)  # Output: [[1, 6], [8, 10]]

def levenshtein(a, b):
    if len(a) == 0:
        return len(b)
    if len(b) == 0:
        return len(a)

    # Create a matrix to store distances
    dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]

    # Initialize the first row and column
    for i in range(len(a) + 1):
        dp[i][0] = i
    for j in range(len(b) + 1):
        dp[0][j] = j

    # Fill the matrix
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                cost = 0
            else:
                cost = 1
            dp[i][j] = min(dp[i - 1][j] + 1,  # Deletion
                           dp[i][j - 1] + 1,  # Insertion
                           dp[i - 1][j - 1] + cost)  # Substitution

    return dp[len(a)][len(b)]

# Demo
if __name__ == "__main__":
    a = "kitten"
    b = "sitting"
    print(f"The edit distance between '{a}' and '{b}' is: {levenshtein(a, b)}")

def parse_duration(text):
    # Split the input text by spaces
    parts = text.split()

    # Initialize total seconds to 0
    total_seconds = 0

    # Define a mapping of units to their corresponding values in seconds
    unit_values = {
        'h': 3600,
        'm': 60,
        's': 1
    }

    # Iterate over the parts and calculate total seconds
    for part in parts:
        if part.isdigit():
            total_seconds += int(part)
        elif part in unit_values:
            total_seconds += unit_values[part]

    return total_seconds

# Example usage
if __name__ == "__main__":
    example_input = '1h30m'
    result = parse_duration(example_input)
    print(f"The duration '{example_input}' is {result} seconds.")

def spiral_order(matrix):
    if not matrix or not matrix[0]:
        return []

    result = []
    top, bottom, left, right = 0, len(matrix) - 1, 0, len(matrix[0]) - 1

    while top <= bottom and left <= right:
        # Traverse from left to right
        for i in range(left, right + 1):
            result.append(matrix[top][i])
        top += 1

        # Traverse from top to bottom
        for i in range(top, bottom + 1):
            result.append(matrix[i][right])
        right -= 1

        if top <= bottom:
            # Traverse from right to left
            for i in range(right, left - 1, -1):
                result.append(matrix[bottom][i])
            bottom -= 1

        if left <= right:
            # Traverse from bottom to top
            for i in range(bottom, top - 1, -1):
                result.append(matrix[i][left])
            left += 1

    return result

# Demo
if __name__ == "__main__":
    matrix = [
        [1, 2, 3],
        [4, 5, 6],
        [7, 8, 9]
    ]
    print(spiral_order(matrix))  # Output: [1, 2, 3, 6, 9, 8, 7, 4, 5]

from typing import List

def group_anagrams(words: List[str]) -> List[List[str]]:
    anagram_groups = {}

    for word in words:
        sorted_word = ''.join(sorted(word))
        if sorted_word not in anagram_groups:
            anagram_groups[sorted_word] = [word]
        else:
            anagram_groups[sorted_word].append(word)

    return list(anagram_groups.values())

# Demo
if __name__ == "__main__":
    words = ["listen", "silent", "enlist", "google", "gooegl", "elvis", "vile"]
    result = group_anagrams(words)
    print(result)

def caesar_cipher(text, shift):
    def shift_char(c):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c) for c in text)

if __name__ == "__main__":
    # Example usage
    text = "Hello, World!"
    shift = 3
    result = caesar_cipher(text, shift)
    print(result)  # Output: Khoor, Zruog!

def pascal_row(n):
    if n < 0:
        return []

    row = [1]
    for i in range(1, n + 1):
        next_row = [1] * (i + 1)
        for j in range(1, i):
            next_row[j] = row[j - 1] + row[j]
        row = next_row
    return row

# Demo
if __name__ == "__main__":
    print(pascal_row(0))  # Output: [1]
    print(pascal_row(4))  # Output: [1, 4, 6, 4, 1]

def dedupe_keep_order(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

# Demo
if __name__ == "__main__":
    example_items = [1, 2, 3, 2, 4, 1, 5]
    print(dedupe_keep_order(example_items))  # Output: [1, 2, 3, 4, 5]

def longest_common_prefix(words):
    if not words:
        return ''

    # Sort the list of words to find the common prefix
    words.sort()

    # Compare the first and last word to find the common prefix
    first_word = words[0]
    last_word = words[-1]

    # Find the common prefix by comparing characters
    common_prefix = ''
    for i in range(min(len(first_word), len(last_word))):
        if first_word[i] == last_word[i]:
            common_prefix += first_word[i]
        else:
            break

    return common_prefix

# Demo
if __name__ == "__main__":
    words = ["flower", "flow", "flight"]
    print(longest_common_prefix(words))  # Output: 'fl'

def binary_search(values, target):
    left, right = 0, len(values) - 1

    while left <= right:
        mid = (left + right) // 2

        if values[mid] == target:
            return mid
        elif values[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

# Demo
if __name__ == "__main__":
    values = [1, 3, 5, 7, 9, 11, 13, 15]
    target = 7
    result = binary_search(values, target)
    print(f"Index of {target} in {values}: {result}")

def deep_flatten(value):
    if isinstance(value, list):
        return [item for sublist in value for item in deep_flatten(sublist)]
    else:
        return [value]

if __name__ == "__main__":
    # Example usage
    nested_list = [1, [2, [3, 4], 5], 6, [7, 8]]
    flat_list = deep_flatten(nested_list)
    print(flat_list)  # Output: [1, 2, 3, 4, 5, 6, 7, 8]

def is_valid_ipv4(address):
    parts = address.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        if not part.isdigit() or (part.startswith('0') and len(part) > 1):
            return False
        if int(part) < 0 or int(part) > 255:
            return False

    return True

# Demo
if __name__ == "__main__":
    test_addresses = [
        "192.168.1.1",
        "0.0.0.0",
        "255.255.255.255",
        "192.168.1.256",
        "192.168.1.-1",
        "192.168.1.001",
        "192.168.1.a",
        "192.168.1",
        "192.168.1.1.1"
    ]

    for address in test_addresses:
        print(f"{address}: {is_valid_ipv4(address)}")

def word_wrap(text, width):
    def wrap_line(line, width):
        if len(line) <= width:
            return [line]
        for i in range(width, -1, -1):
            if line[i] == ' ':
                return [line[:i], *wrap_line(line[i + 1:], width)]
        return [line]

    lines = []
    current_line = ''
    for word in text.split():
        if len(current_line) + len(word) + 1 <= width:
            current_line += f" {word}"
        else:
            lines.extend(wrap_line(current_line, width))
            current_line = word
    lines.extend(wrap_line(current_line, width))
    return lines

# Demo
if __name__ == "__main__":
    text = "This is a sample text that needs to be wrapped into lines of at most 10 characters."
    width = 10
    result = word_wrap(text, width)
    print(result)

def count_islands(grid):
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = set()

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == '0' or (r, c) in visited:
            return
        visited.add((r, c))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            dfs(r + dr, c + dc)

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1' and (r, c) not in visited:
                dfs(r, c)
                count += 1

    return count

# Demo
grid = [
    "11000",
    "11000",
    "00100",
    "00011"
]
print(count_islands(grid))  # Output: 3

def next_greater(values):
    stack = []
    result = [-1] * len(values)

    for i, value in enumerate(values):
        while stack and values[stack[-1]] < value:
            result[stack.pop()] = value
        stack.append(i)

    return result

# Demo
if __name__ == "__main__":
    input_values = [2, 1, 3]
    output = next_greater(input_values)
    print(output)  # Output: [3, 3, -1]

