  background-color: var(--accent-color);
  border-color: var(--accent-color);
}

.plan-card h2 {
  font-size: 1.5rem;
  margin-bottom: var(--spacing);
}

.plan-card p {
  font-size: 1rem;
  line-height: 1.6;
}

.plan-card button {
  background-color: var(--accent-color);
  color: #fff;
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

