/**
 * Debounce function to limit the number of times a function is called.
 * @param {Function} func - The function to debounce.
 * @param {number} wait - The time in milliseconds to wait before calling the function.
 * @returns {Function} A debounced version of the function.
 */
function debounce(func, wait) {
  let timeout;
  return function(...args) {
    clearTimeout(timeout);
    timeout = setTimeout(() => func.apply(this, args), wait);
  };
}

/**
 * Throttle function to limit the rate at which a function is called.
 * @param {Function} func - The function to throttle.
 * @param {number} limit - The maximum number of times the function can be called in a given time frame.
 * @param {boolean} leading - Whether to call the function on the leading edge of the interval.
 * @returns {Function} A throttled version of the function.
 */
function throttle(func, limit, leading) {
  let lastCall = 0;
  let lastInvoke = 0;
  const trailingDebounce = debounce(func, limit);

  return function(...args) {
    const now = Date.now();
    const remaining = limit - (now - lastInvoke);
    if (!leading && !lastCall) {
      lastCall = now;
      func.apply(this, args);
      return;
    }
    if (remaining <= 0 || remaining > limit) {
      trailingDebounce(...args);
      lastInvoke = now;
    } else if (!leading) {
      timeout = setTimeout(() => trailingDebounce(...args), remaining);
    }
  };
}

// Demo
const logDebounce = debounce(() => console.log('Debounce fired'), 1000);
const logThrottle = throttle(() => console.log('Throttle fired'), 500, true);

document.addEventListener('keydown', () => {
  logDebounce();
  logThrottle();
});
